/**
 * Retrieve derived kanji (Phả hệ nở rộng) for a given kanji or radical.
 * Returns empty array if none found.
 */
export function getKanjiDescendants(kanjiChar: string): KanjiDescendantNode[] {
  if (!kanjiChar) return []
  const norm = kanjiChar.normalize('NFKD')
  return KANJI_DESCENDANTS_MAP[kanjiChar] || KANJI_DESCENDANTS_MAP[norm] || []
}
